const english={};
document.querySelectorAll("[data-i18n]").forEach(el=>english[el.dataset.i18n]=el.innerHTML);
let language="en";
const toggle=document.getElementById("languageToggle");
function setLanguage(next){language=next;document.documentElement.lang=next;document.documentElement.dir=next==="ar"?"rtl":"ltr";const dictionary=next==="es"?es:next==="ar"?ar:english;document.querySelectorAll("[data-i18n]").forEach(el=>{const value=dictionary[el.dataset.i18n];if(value!==undefined)el.innerHTML=value});const labels={en:"Cambiar idioma",es:"تغيير اللغة",ar:"Switch language"};toggle.setAttribute("aria-label",labels[next]);toggle.querySelectorAll("span").forEach((el,i)=>el.style.opacity=(next==="en"&&i===0)||(next==="es"&&i===1)||(next==="ar"&&i===2)?"1":".42");localStorage.setItem("wbm-language",next)}
toggle.addEventListener("click",()=>setLanguage(language==="en"?"es":language==="es"?"ar":"en"));

const menu=document.getElementById("menuToggle"),mobileMenu=document.getElementById("mobileMenu");
menu.addEventListener("click",()=>{const open=mobileMenu.classList.toggle("open");menu.setAttribute("aria-expanded",String(open));mobileMenu.setAttribute("aria-hidden",String(!open))});
mobileMenu.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{mobileMenu.classList.remove("open");menu.setAttribute("aria-expanded","false");mobileMenu.setAttribute("aria-hidden","true")}));

const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("visible");observer.unobserve(entry.target)}}),{threshold:.12});
document.querySelectorAll(".reveal").forEach(el=>observer.observe(el));
document.getElementById("year").textContent=new Date().getFullYear();
setLanguage(["en","es","ar"].includes(localStorage.getItem("wbm-language"))?localStorage.getItem("wbm-language"):"en");
